:root {
  --ink: #241a15;
  --cream: #f6e7c6;
  --paper: #fdf6e3;
  --red: #d9452f;
  --gold: #e9b44c;
  --teal: #2f7d76;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #120d0b;
  color: var(--ink);
  font-family: "Georgia", "Times New Roman", serif;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

#app {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  background:
    radial-gradient(ellipse at 50% 42%, #3a2a20 0%, #1a1210 55%, #0c0908 100%);
}

/* Film-grain / vignette on the cabinet */
#app::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at center, transparent 45%, rgba(0,0,0,.55) 100%);
  mix-blend-mode: multiply;
  z-index: 50;
}

.stage {
  position: relative;
  width: min(100vw, 177.78vh);
  height: min(56.25vw, 100vh);
  max-width: 1600px;
  box-shadow:
    0 0 0 6px #2a1d16,
    0 0 0 10px #c9a86e,
    0 0 0 13px #2a1d16,
    0 30px 80px rgba(0, 0, 0, .75);
  overflow: hidden;
  background: #f6e7c6;
  border-radius: 4px;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: auto;
}

.hidden { display: none !important; }

/* ---------- Title screen button ---------- */
.title-ui {
  position: absolute;
  left: 50%;
  bottom: 8.5%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  z-index: 20;
  transition: opacity .3s ease, transform .3s ease;
}

.title-ui.gone {
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 10px);
}

.start-btn {
  font-family: "Georgia", serif;
  font-weight: 900;
  letter-spacing: .22em;
  font-size: clamp(15px, 2.3vw, 27px);
  color: #2b1d17;
  padding: .62em 1.75em .56em 1.95em;
  background: linear-gradient(#ffe9ad, #e9b44c 55%, #cf912f);
  border: 3px solid #2b1d17;
  border-radius: 6px;
  box-shadow: 0 5px 0 #2b1d17, 0 10px 24px rgba(0,0,0,.45), inset 0 2px 0 rgba(255,255,255,.6);
  cursor: pointer;
  transform: rotate(-1deg);
  transition: transform .12s ease, box-shadow .12s ease, filter .12s ease;
}

.start-btn:hover { filter: brightness(1.06); transform: rotate(-1deg) translateY(-2px); }
.start-btn:active { transform: rotate(-1deg) translateY(4px); box-shadow: 0 1px 0 #2b1d17, 0 4px 12px rgba(0,0,0,.4); }

.title-hint {
  font-size: clamp(8px, 1.05vw, 13px);
  letter-spacing: .18em;
  text-transform: uppercase;
  color: #efe0c0;
  text-shadow: 0 1px 2px rgba(0,0,0,.8);
  opacity: .85;
  white-space: nowrap;
}

/* ---------- Touch controls ---------- */
.touch {
  position: absolute;
  inset: 0;
  z-index: 30;
  pointer-events: none;
}

.pad {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: max(16px, env(safe-area-inset-bottom));
  width: clamp(96px, 16vh, 150px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: rgba(20, 14, 11, .28);
  border: 2px solid rgba(246, 231, 198, .38);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(2px);
}

.pad-ring {
  position: absolute;
  inset: 20%;
  border-radius: 50%;
  border: 2px dashed rgba(246, 231, 198, .28);
}

.pad-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44%;
  aspect-ratio: 1;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 35% 30%, #ffe9ad, #d99a3a 70%, #a86a20);
  border: 2px solid rgba(36, 26, 21, .8);
  box-shadow: 0 3px 10px rgba(0,0,0,.5);
}

.right-btns {
  position: absolute;
  right: max(14px, env(safe-area-inset-right));
  bottom: max(14px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: repeat(3, auto);
  grid-template-areas:
    ".    sup  swap"
    "jump dash fire";
  gap: clamp(6px, 1.2vh, 12px);
  align-items: end;
  justify-items: end;
  pointer-events: none;
}

.tbtn {
  pointer-events: auto;
  touch-action: none;
  font-family: "Georgia", serif;
  font-weight: 900;
  font-size: clamp(8px, 1.25vh, 13px);
  letter-spacing: .08em;
  color: #fdf6e3;
  width: clamp(52px, 8.6vh, 78px);
  height: clamp(52px, 8.6vh, 78px);
  border-radius: 50%;
  border: 2px solid rgba(253, 246, 227, .55);
  background: radial-gradient(circle at 35% 28%, rgba(80,60,48,.85), rgba(30,20,16,.82));
  box-shadow: 0 4px 12px rgba(0,0,0,.45);
  display: grid;
  place-items: center;
  line-height: 1;
  padding: 0;
}

.tbtn span { transform: translateY(1px); }
.tbtn em {
  display: block;
  font-style: normal;
  font-size: .72em;
  opacity: .8;
  margin-top: 3px;
  letter-spacing: .04em;
}
.tbtn:active, .tbtn.on { transform: scale(.93); background: radial-gradient(circle at 35% 28%, #e9b44c, #a05f1d); color: #2b1d17; }
.tbtn-fire { background: radial-gradient(circle at 35% 28%, rgba(190,70,50,.9), rgba(90,22,18,.85)); width: clamp(60px, 10vh, 88px); height: clamp(60px, 10vh, 88px); }
.tbtn-jump { background: radial-gradient(circle at 35% 28%, rgba(60,130,120,.9), rgba(20,60,58,.85)); }
.tbtn-dash { background: radial-gradient(circle at 35% 28%, rgba(90,90,140,.9), rgba(30,30,60,.85)); grid-area: dash; }
.tbtn-super {
  grid-area: sup;
  width: clamp(46px, 7.4vh, 66px);
  height: clamp(46px, 7.4vh, 66px);
  background: radial-gradient(circle at 35% 28%, rgba(234,180,76,.95), rgba(120,70,20,.9));
  color: #2b1d17;
}
.tbtn-sm {
  grid-area: swap;
  width: clamp(44px, 7vh, 62px);
  height: clamp(44px, 7vh, 62px);
  font-size: clamp(7px, 1.05vh, 10px);
}
.tbtn-jump { grid-area: jump; }
.tbtn-fire { grid-area: fire; }
.tbtn-super em { font-size: .62em; }

.pause-btn {
  position: absolute;
  top: max(10px, env(safe-area-inset-top));
  right: max(10px, env(safe-area-inset-right));
  z-index: 31;
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 2px solid rgba(253, 246, 227, .5);
  background: rgba(20, 14, 11, .45);
  color: #fdf6e3;
  font-family: sans-serif;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 1px;
  cursor: pointer;
}

/* Portrait phones: park the controls under the screen instead of over it */
@media (orientation: portrait) and (pointer: coarse) {
  #app { place-items: start center; padding-top: max(2vh, env(safe-area-inset-top)); }
  .stage { width: 100vw; height: 56.25vw; box-shadow: 0 0 0 3px #2a1d16, 0 8px 30px #000; }
  .touch { inset: auto 0 0 0; height: calc(100vh - 56.25vw - 2vh); pointer-events: none; }
  .pad { left: max(22px, env(safe-area-inset-left)); bottom: auto; top: 12%; width: min(34vw, 190px); }
  .right-btns { right: max(18px, env(safe-area-inset-right)); bottom: auto; top: 10%; transform: scale(1.05); }
  .tbtn { width: min(14vw, 76px); height: min(14vw, 76px); font-size: 10px; }
  .tbtn-fire { width: min(17vw, 88px); height: min(17vw, 88px); }
  .tbtn-super, .tbtn-sm { width: min(11vw, 64px); height: min(11vw, 64px); }
  .title-hint { display: none; }
  .pause-btn { top: 6px; right: 8px; width: 30px; height: 30px; }
}

/* Very short landscape phones */
@media (orientation: landscape) and (max-height: 430px) {
  .pad { width: 88px; }
  .right-btns { transform: scale(.9); transform-origin: bottom right; }
  .title-hint { display: none; }
}

// Shared math, palette and small canvas helpers.
export const TAU = Math.PI * 2;
export const W = 1280;
export const H = 720;
export const GROUND = 640;

export const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
export const lerp = (a, b, t) => a + (b - a) * t;
export const approach = (v, target, step) => (v < target ? Math.min(v + step, target) : Math.max(v - step, target));
export const rand = (a = 1, b = 0) => b + Math.random() * (a - b);
export const randInt = (a, b) => Math.floor(rand(b + 1, a));
export const choice = (arr) => arr[(Math.random() * arr.length) | 0];
export const dist2 = (ax, ay, bx, by) => (ax - bx) ** 2 + (ay - by) ** 2;
export const easeOut = (t) => 1 - (1 - t) ** 3;
export const easeInOut = (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2);
export const easeOutBack = (t) => 1 + 2.70158 * (t - 1) ** 3 + 1.70158 * (t - 1) ** 2;
export const sign = (v) => (v < 0 ? -1 : 1);

export const PAL = {
  ink: '#2b1d17',
  inkSoft: '#4a342a',
  cream: '#f6e7c6',
  paper: '#fdf6e3',
  red: '#d9452f',
  redDark: '#8f2417',
  gold: '#e9b44c',
  goldDark: '#b07a22',
  teal: '#2f7d76',
  tealDark: '#1c4f4a',
  blue: '#4f7fbf',
  pink: '#ff7fae',
  pinkHot: '#ff3d7f',
  green: '#6a9c3f',
  purple: '#6c4a7d',
  brown: '#84512f',
  white: '#fffaf0',
  shadow: 'rgba(43,29,23,.25)',
};

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function fillRound(ctx, x, y, w, h, r, fill, stroke = PAL.ink, lw = 3) {
  roundRect(ctx, x, y, w, h, r);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke && lw) { ctx.lineWidth = lw; ctx.strokeStyle = stroke; ctx.stroke(); }
}

export function ellipse(ctx, x, y, rx, ry, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, Math.abs(rx), Math.abs(ry), rot, 0, TAU);
}

export function fillEllipse(ctx, x, y, rx, ry, fill, stroke = PAL.ink, lw = 3, rot = 0) {
  ellipse(ctx, x, y, rx, ry, rot);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke && lw) { ctx.lineWidth = lw; ctx.strokeStyle = stroke; ctx.stroke(); }
}

export function starPath(ctx, x, y, outer, inner, points, rot = -Math.PI / 2) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const r = i % 2 === 0 ? outer : inner;
    const a = rot + (i * Math.PI) / points;
    const px = x + Math.cos(a) * r;
    const py = y + Math.sin(a) * r;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

export function drawStar(ctx, x, y, outer, inner, points, fill, stroke, lw = 3, rot = -Math.PI / 2) {
  starPath(ctx, x, y, outer, inner, points, rot);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.lineWidth = lw; ctx.strokeStyle = stroke; ctx.stroke(); }
}

export function inkText(ctx, text, x, y, size, opts = {}) {
  const {
    font = 'Georgia, "Times New Roman", serif',
    weight = '900',
    align = 'center',
    baseline = 'middle',
    fill = PAL.paper,
    stroke = PAL.ink,
    lw = Math.max(2, size * 0.09),
    shadow = 0,
    letter = 0,
  } = opts;
  ctx.save();
  ctx.font = `${weight} ${size}px ${font}`;
  ctx.textAlign = align;
  ctx.textBaseline = baseline;
  if (letter) ctx.letterSpacing = `${letter}px`;
  if (shadow) {
    ctx.lineWidth = lw + 1;
    ctx.strokeStyle = 'rgba(20,12,9,.55)';
    ctx.strokeText(text, x + shadow, y + shadow);
    ctx.fillStyle = 'rgba(20,12,9,.45)';
    ctx.fillText(text, x + shadow, y + shadow);
  }
  if (lw) {
    ctx.lineJoin = 'round';
    ctx.lineWidth = lw;
    ctx.strokeStyle = stroke;
    ctx.strokeText(text, x, y);
  }
  ctx.fillStyle = fill;
  ctx.fillText(text, x, y);
  ctx.restore();
}

// Sparks / debris, shared by every boss.
export class Particles {
  constructor() { this.items = []; }
  clear() { this.items.length = 0; }
  add(p) {
    if (this.items.length > 520) this.items.shift();
    this.items.push({
      x: p.x, y: p.y, vx: p.vx || 0, vy: p.vy || 0,
      life: p.life ?? 0.5, max: p.life ?? 0.5,
      size: p.size ?? 4, color: p.color || PAL.gold,
      grav: p.grav ?? 900, drag: p.drag ?? 2.4,
      kind: p.kind || 'dot', rot: p.rot ?? rand(TAU),
      spin: p.spin ?? rand(8, -8), layer: p.layer || 1,
    });
  }
  burst(x, y, n, color, opts = {}) {
    for (let i = 0; i < n; i++) {
      const a = opts.angle ?? rand(TAU);
      const sp = (opts.speed ?? 240) * rand(1.2, 0.25);
      this.add({
        x, y,
        vx: Math.cos(a + rand(0.6, -0.6)) * sp,
        vy: Math.sin(a + rand(0.6, -0.6)) * sp,
        life: (opts.life ?? 0.5) * rand(1.4, 0.6),
        size: (opts.size ?? 5) * rand(1.5, 0.5),
        color: Array.isArray(color) ? choice(color) : color,
        grav: opts.grav ?? 900,
        kind: opts.kind || 'spark',
        drag: opts.drag ?? 2.2,
      });
    }
  }
  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const p = this.items[i];
      p.life -= dt;
      if (p.life <= 0) { this.items.splice(i, 1); continue; }
      p.vy += p.grav * dt;
      const d = 1 - Math.min(0.9, p.drag * dt);
      p.vx *= d; p.vy *= d;
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.rot += p.spin * dt;
    }
  }
  draw(ctx) {
    for (const p of this.items) {
      const t = Math.max(0, p.life / p.max);
      ctx.save();
      ctx.globalAlpha = Math.min(1, t * 2.4);
      ctx.translate(p.x, p.y);
      ctx.rotate(p.rot);
      if (p.kind === 'spark') {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = Math.max(1.5, p.size * 0.55 * t);
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(-p.size, 0);
        ctx.lineTo(p.size, 0);
        ctx.stroke();
      } else if (p.kind === 'star') {
        drawStar(ctx, 0, 0, p.size, p.size * 0.45, 4, p.color, null, 0);
      } else if (p.kind === 'ring') {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = Math.max(1, p.size * 0.35 * t);
        ctx.beginPath();
        ctx.arc(0, 0, p.size * (1.6 - t), 0, TAU);
        ctx.stroke();
      } else if (p.kind === 'leaf') {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.ellipse(0, 0, p.size * 1.4, p.size * 0.55, 0, 0, TAU);
        ctx.fill();
      } else {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(0, 0, Math.max(0.5, p.size * t), 0, TAU);
        ctx.fill();
      }
      ctx.restore();
    }
  }
}

// Tiny deterministic noise for film grain.
let grainCanvas = null;
export function filmGrain(ctx, t, strength = 0.07) {
  if (!grainCanvas) {
    grainCanvas = document.createElement('canvas');
    grainCanvas.width = 160; grainCanvas.height = 90;
    const g = grainCanvas.getContext('2d');
    const img = g.createImageData(160, 90);
    for (let i = 0; i < img.data.length; i += 4) {
      const v = (Math.random() * 255) | 0;
      img.data[i] = v; img.data[i + 1] = v; img.data[i + 2] = v; img.data[i + 3] = 255;
    }
    g.putImageData(img, 0, 0);
  }
  ctx.save();
  ctx.globalAlpha = strength;
  ctx.globalCompositeOperation = 'overlay';
  const off = (Math.floor(t * 24) % 4) * 37;
  ctx.translate(-off, -off * 0.6);
  ctx.drawImage(grainCanvas, 0, 0, W + 160, H + 160);
  ctx.restore();
}

// Procedural 1930s-ish jazz loop + chunky cartoon SFX, no external assets.
const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

const TRACKS = [
  { bpm: 138, root: 45, mode: [0, 2, 3, 5, 7, 8, 10], prog: [0, 5, 1, 4], bright: 1.0 },   // field romp
  { bpm: 150, root: 44, mode: [0, 2, 3, 5, 7, 9, 10], prog: [0, 3, 4, 2], bright: 0.9 },   // bee swing
  { bpm: 126, root: 43, mode: [0, 2, 3, 5, 6, 8, 10], prog: [0, 5, 3, 4], bright: 0.75 },  // pirate dirge
  { bpm: 132, root: 47, mode: [0, 1, 3, 5, 7, 8, 11], prog: [0, 5, 1, 4], bright: 0.85 },  // ice waltz-ish
  { bpm: 158, root: 42, mode: [0, 2, 3, 5, 7, 8, 11], prog: [0, 1, 5, 4], bright: 1.0 },   // devil stomp
];

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.musicOn = true;
    this.track = 0;
    this.intensity = 0;
    this.step = 0;
    this.nextTime = 0;
    this.timer = null;
    this.melodySeed = 0;
    this.lastShot = 0;
  }

  unlock() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.9;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.16;
      this.musicGain.connect(this.master);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.38;
      this.sfxGain.connect(this.master);
      this.noise = this.makeNoise();
      this.startMusic();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }

  makeNoise() {
    const len = this.ctx.sampleRate * 1.2;
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    return buf;
  }

  setTrack(i) {
    this.track = i % TRACKS.length;
    this.step = 0;
    this.melodySeed = (this.melodySeed + 7) % 11;
    if (this.ctx) {
      this.nextTime = Math.max(this.nextTime, this.ctx.currentTime + 0.05);
    }
  }

  setIntensity(v) { this.intensity = v; }

  startMusic() {
    if (!this.ctx || this.timer) return;
    this.nextTime = this.ctx.currentTime + 0.08;
    this.timer = setInterval(() => this.scheduler(), 45);
  }

  stopMusic() {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  scheduler() {
    if (!this.ctx || !this.musicOn) return;
    const t = TRACKS[this.track];
    const spb = 60 / t.bpm;
    const stepDur = spb / 2; // eighth notes
    while (this.nextTime < this.ctx.currentTime + 0.2) {
      this.scheduleStep(this.step, this.nextTime, t, stepDur);
      this.step = (this.step + 1) % 32;
      this.nextTime += stepDur;
    }
  }

  scheduleStep(step, time, t, stepDur) {
    const bar = Math.floor(step / 8) % 4;
    const inBar = step % 8;
    const chordRoot = t.root + t.prog[bar];
    const swing = inBar % 2 === 1 ? stepDur * 0.12 : 0;
    const at = time + swing;
    const loud = this.intensity > 0.5;

    // Walking bass
    if (inBar === 0 || inBar === 2 || inBar === 4 || inBar === 6) {
      const walk = inBar === 6 ? 7 : inBar === 2 ? 5 : 0;
      this.bass(midi(chordRoot + (inBar === 4 ? 7 : walk) - 12), at, 0.24, inBar === 0 ? 0.5 : 0.34);
    }
    // Chord stabs on the "and"
    if (inBar === 3 || inBar === 7) {
      const deg = [0, 3, 7, 10];
      this.stab(deg.map((d) => midi(chordRoot + d + 12)), at, 0.11, 0.09);
    }
    // Melody: simple generated phrase from the mode
    if (this.musicOn && (inBar === 0 || inBar === 2 || inBar === 3 || inBar === 5 || inBar === 6)) {
      const phrase = [0, 4, 2, 3, 6, 4, 1, 0];
      const idx = (step + this.melodySeed + bar * 3) % phrase.length;
      let deg = phrase[idx];
      if (inBar === 3 && Math.random() < 0.5) deg += 1;
      const semi = t.mode[deg % t.mode.length] + 12 * Math.floor(deg / t.mode.length);
      this.lead(midi(chordRoot + semi + 12), at + (inBar === 6 ? stepDur * 0.1 : 0), 0.16, 0.075 * t.bright);
    }
    // Drums
    if (inBar === 0 || inBar === 4) this.kick(at, 0.3);
    if (inBar === 2 || inBar === 6) this.snare(at, loud ? 0.22 : 0.14);
    this.hat(at, inBar % 2 === 0 ? 0.055 : 0.03);
    if (loud && (inBar === 3 || inBar === 7)) this.hat(at, 0.05, true);
  }

  osc(type, freq, t, dur, vol, dest, filterFreq, slideTo) {
    if (!this.ctx) return;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slideTo) o.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    if (filterFreq) {
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass'; f.frequency.value = filterFreq;
      o.connect(f); f.connect(g);
    } else o.connect(g);
    g.connect(dest || this.musicGain);
    o.start(t); o.stop(t + dur + 0.02);
  }

  bass(freq, t, dur, vol) { this.osc('triangle', freq, t, dur, vol, this.musicGain, 420); }
  stab(freqs, t, dur, vol) {
    for (const f of freqs) this.osc('sawtooth', f, t, dur, vol, this.musicGain, 1600);
  }
  lead(freq, t, dur, vol) {
    this.osc('square', freq, t, dur, vol, this.musicGain, 2400);
    this.osc('triangle', freq * 2, t, dur * 0.6, vol * 0.4, this.musicGain, 3200);
  }
  kick(t, vol) { this.osc('sine', 120, t, 0.12, vol, this.musicGain, null, 42); }
  snare(t, vol) {
    this.noiseHit(t, 0.09, vol, 1800, this.musicGain);
    this.osc('triangle', 180, t, 0.07, vol * 0.5, this.musicGain, null, 90);
  }
  hat(t, vol, open) {
    this.noiseHit(t, open ? 0.12 : 0.03, vol, 8000, this.musicGain);
  }

  noiseHit(t, dur, vol, hp, dest) {
    if (!this.ctx) return;
    const s = this.ctx.createBufferSource();
    s.buffer = this.noise;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const f = this.ctx.createBiquadFilter();
    f.type = 'highpass'; f.frequency.value = hp;
    s.connect(f); f.connect(g); g.connect(dest || this.sfxGain);
    s.start(t, Math.random() * 0.3, dur + 0.02);
  }

  // ---- SFX ----
  fx(name, pitch = 1) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime;
    switch (name) {
      case 'shoot':
        this.osc('square', 620 * pitch, t, 0.055, 0.1, this.sfxGain, 2400, 220 * pitch);
        break;
      case 'shoot2':
        this.noiseHit(t, 0.05, 0.07, 1200, this.sfxGain);
        this.osc('triangle', 340 * pitch, t, 0.07, 0.06, this.sfxGain, null, 180);
        break;
      case 'chaser':
        this.osc('sine', 900 * pitch, t, 0.07, 0.05, this.sfxGain, null, 1500);
        break;
      case 'lob':
        this.osc('triangle', 240, t, 0.14, 0.12, this.sfxGain, 900, 520);
        break;
      case 'hit':
        this.noiseHit(t, 0.06, 0.07, 2500, this.sfxGain);
        this.osc('square', 200, t, 0.05, 0.035, this.sfxGain, null, 120);
        break;
      case 'hurt':
        this.osc('sawtooth', 320, t, 0.3, 0.24, this.sfxGain, 1200, 90);
        this.noiseHit(t, 0.2, 0.12, 500, this.sfxGain);
        break;
      case 'jump':
        this.osc('square', 300, t, 0.1, 0.07, this.sfxGain, 1800, 660);
        break;
      case 'dash':
        this.noiseHit(t, 0.16, 0.1, 1400, this.sfxGain);
        break;
      case 'parry':
        this.osc('sine', 880, t, 0.22, 0.16, this.sfxGain, null, 1760);
        this.osc('sine', 1320, t + 0.05, 0.2, 0.1, this.sfxGain, null, 2200);
        break;
      case 'super':
        [220, 277, 330, 440].forEach((f, i) => this.osc('sawtooth', f, t + i * 0.03, 0.8, 0.1, this.sfxGain, 2000));
        this.noiseHit(t, 0.5, 0.15, 400, this.sfxGain);
        break;
      case 'superShot':
        this.osc('sawtooth', 120, t, 0.3, 0.12, this.sfxGain, 1200, 60);
        break;
      case 'ko':
        [130, 98, 65].forEach((f, i) => this.osc('sine', f, t + i * 0.08, 1.4, 0.22, this.sfxGain, null, f * 0.5));
        this.noiseHit(t, 0.7, 0.16, 200, this.sfxGain);
        break;
      case 'death':
        [320, 240, 180, 120].forEach((f, i) => this.osc('triangle', f, t + i * 0.12, 0.5, 0.16, this.sfxGain, 900));
        break;
      case 'select':
        this.osc('square', 660, t, 0.06, 0.08, this.sfxGain, null, 990);
        break;
      case 'telegraph':
        this.osc('sawtooth', 140, t, 0.18, 0.06, this.sfxGain, 600, 280);
        break;
      case 'heal':
        this.osc('sine', 700, t, 0.3, 0.1, this.sfxGain, null, 1400);
        break;
      case 'explode':
        this.noiseHit(t, 0.4, 0.2, 300, this.sfxGain);
        this.osc('sine', 90, t, 0.35, 0.18, this.sfxGain, null, 40);
        break;
    }
  }

  toggleMute() {
    this.enabled = !this.enabled;
    if (this.master) this.master.gain.value = this.enabled ? 0.9 : 0;
    return this.enabled;
  }
}

// Five hand-drawn arenas. Static layers are cached; ambient motion is drawn live.
import { W, H, TAU, PAL, rand, ellipse, fillEllipse, roundRect, fillRound, drawStar, clamp } from './util.js';

const cache = new Map();

function staticLayer(key, paint) {
  let c = cache.get(key);
  if (c) return c;
  c = document.createElement('canvas');
  c.width = W; c.height = H;
  paint(c.getContext('2d'));
  cache.set(key, c);
  return c;
}

function sky(ctx, stops) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  stops.forEach(([p, c]) => g.addColorStop(p, c));
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function cloud(ctx, x, y, s, alpha = 1, color = '#fff8e7') {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.strokeStyle = 'rgba(70,50,35,.28)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(x, y, 26 * s, Math.PI, 0);
  ctx.arc(x + 34 * s, y - 12 * s, 34 * s, Math.PI * 1.05, Math.PI * 1.95);
  ctx.arc(x + 78 * s, y, 26 * s, Math.PI * 1.15, 0);
  ctx.arc(x + 40 * s, y + 6 * s, 31 * s, 0, Math.PI);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();
  ctx.restore();
}

function grassTuft(ctx, x, y, s, color = '#4f7a2f') {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = 3 * s;
  ctx.lineCap = 'round';
  for (let i = -1; i <= 1; i++) {
    ctx.beginPath();
    ctx.moveTo(x + i * 6 * s, y);
    ctx.quadraticCurveTo(x + i * 9 * s, y - 12 * s, x + i * 15 * s, y - 17 * s);
    ctx.stroke();
  }
  ctx.restore();
}

// ---------------- FIELD ----------------
function fieldStatic(ctx) {
  sky(ctx, [[0, '#8fd6d0'], [0.38, '#f9e2a8'], [0.7, '#f7c87e'], [1, '#e8a95e']]);
  // sun
  ctx.save();
  ctx.translate(1050, 150);
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = '#fff3bd';
  for (let i = 0; i < 12; i++) {
    ctx.rotate(TAU / 12);
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(-38, -230); ctx.lineTo(38, -230);
    ctx.closePath(); ctx.fill();
  }
  ctx.globalAlpha = 1;
  fillEllipse(ctx, 0, 0, 82, 82, '#ffe9a3', '#e5b45c', 4);
  ctx.restore();
  // clouds
  cloud(ctx, 120, 150, 1.1, 0.9, '#fff7e6');
  cloud(ctx, 520, 120, 0.8, 0.75, '#fff7e6');
  cloud(ctx, 860, 200, 0.65, 0.65, '#fff7e6');
  // distant hills
  ctx.fillStyle = '#c9b16b';
  ctx.beginPath();
  ctx.moveTo(0, 470);
  ctx.bezierCurveTo(180, 380, 330, 400, 500, 460);
  ctx.bezierCurveTo(700, 520, 820, 400, 980, 430);
  ctx.bezierCurveTo(1120, 455, 1200, 480, 1280, 470);
  ctx.lineTo(1280, 640); ctx.lineTo(0, 640); ctx.closePath(); ctx.fill();
  ctx.fillStyle = '#a5a052';
  ctx.beginPath();
  ctx.moveTo(0, 520);
  ctx.bezierCurveTo(240, 460, 400, 500, 620, 520);
  ctx.bezierCurveTo(860, 540, 1020, 470, 1280, 510);
  ctx.lineTo(1280, 640); ctx.lineTo(0, 640); ctx.closePath(); ctx.fill();
  // barn + silo
  ctx.save();
  ctx.translate(180, 500);
  ctx.fillStyle = '#b4442e';
  ctx.strokeStyle = PAL.ink;
  ctx.lineWidth = 3;
  ctx.fillRect(-55, -80, 110, 100);
  ctx.strokeRect(-55, -80, 110, 100);
  ctx.fillStyle = '#8f2f20';
  ctx.beginPath();
  ctx.moveTo(-70, -78); ctx.lineTo(0, -140); ctx.lineTo(70, -78); ctx.closePath();
  ctx.fill(); ctx.stroke();
  ctx.fillStyle = '#6d2116';
  ctx.fillRect(-22, -36, 44, 56);
  ctx.strokeRect(-22, -36, 44, 56);
  ctx.strokeStyle = '#f4dba6'; ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(-18, -36); ctx.lineTo(18, 18); ctx.moveTo(18, -36); ctx.lineTo(-18, 18); ctx.stroke();
  ctx.fillStyle = '#cbb78b';
  ctx.fillRect(78, -130, 34, 150); ctx.strokeRect(78, -130, 34, 150);
  ctx.fillStyle = '#8f2f20';
  ctx.beginPath(); ctx.ellipse(95, -130, 22, 14, 0, Math.PI, 0); ctx.fill(); ctx.stroke();
  ctx.restore();
  // fence
  ctx.strokeStyle = '#7c5a36'; ctx.lineWidth = 5;
  for (let x = 0; x < W; x += 78) {
    ctx.beginPath(); ctx.moveTo(x + 20, 545); ctx.lineTo(x + 20, 610); ctx.stroke();
  }
  ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(0, 562); ctx.lineTo(W, 562); ctx.moveTo(0, 592); ctx.lineTo(W, 592); ctx.stroke();
  // soil
  const dirt = ctx.createLinearGradient(0, 610, 0, H);
  dirt.addColorStop(0, '#b8794a'); dirt.addColorStop(0.25, '#94582f'); dirt.addColorStop(1, '#6b3c22');
  ctx.fillStyle = dirt;
  ctx.beginPath();
  ctx.moveTo(0, 620);
  ctx.bezierCurveTo(200, 606, 420, 630, 640, 618);
  ctx.bezierCurveTo(860, 606, 1080, 632, 1280, 616);
  ctx.lineTo(1280, H); ctx.lineTo(0, H); ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(60,36,20,.5)'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(0, 621); ctx.bezierCurveTo(200, 607, 420, 631, 640, 619);
  ctx.bezierCurveTo(860, 607, 1080, 633, 1280, 617); ctx.stroke();
  // crop rows
  ctx.strokeStyle = 'rgba(78,46,26,.38)';
  ctx.lineWidth = 3;
  for (let i = 0; i < 9; i++) {
    const y = 650 + i * 11;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 40) ctx.lineTo(x, y + Math.sin(x * 0.02 + i) * 3);
    ctx.stroke();
  }
  for (let x = 40; x < W; x += 96) grassTuft(ctx, x, 632, 1, '#4d7029');
  // scattered pebbles
  ctx.fillStyle = '#7e4b2b';
  for (let i = 0; i < 26; i++) {
    ellipse(ctx, rand(W), rand(700, 635), rand(5, 2), rand(3, 1));
    ctx.fill();
  }
}

// ---------------- HIVE (sky) ----------------
function hiveStatic(ctx) {
  sky(ctx, [[0, '#3f9bc4'], [0.42, '#8fd4e6'], [0.78, '#ffe4b0'], [1, '#f6c987']]);
  // giant honeycomb ghost
  ctx.save();
  ctx.globalAlpha = 0.13;
  ctx.strokeStyle = '#7a4a13';
  ctx.lineWidth = 5;
  const R = 74;
  for (let row = -1; row < 7; row++) {
    for (let col = -1; col < 12; col++) {
      const cx = col * R * 1.5 + (row % 2 ? R * 0.75 : 0);
      const cy = row * R * 0.86 - 30;
      ctx.beginPath();
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * TAU + Math.PI / 6;
        const px = cx + Math.cos(a) * R * 0.9;
        const py = cy + Math.sin(a) * R * 0.9;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath(); ctx.stroke();
    }
  }
  ctx.restore();
  // distant hive towers
  ctx.fillStyle = 'rgba(122,74,19,.35)';
  ctx.strokeStyle = 'rgba(70,42,12,.35)';
  ctx.lineWidth = 3;
  for (let i = 0; i < 4; i++) {
    const x = 100 + i * 340, w = 150, h = 120 + (i % 2) * 80;
    ctx.beginPath();
    ctx.moveTo(x, 560);
    ctx.bezierCurveTo(x + w * 0.1, 560 - h, x + w * 0.9, 560 - h, x + w, 560);
    ctx.closePath();
    ctx.fill(); ctx.stroke();
  }
  // clouds
  cloud(ctx, 60, 240, 1.2, 0.8, '#fff9e9');
  cloud(ctx, 430, 170, 0.9, 0.65, '#fff9e9');
  cloud(ctx, 900, 260, 1.3, 0.8, '#fff9e9');
  cloud(ctx, 1120, 160, 0.7, 0.55, '#fff9e9');
  // cloud sea floor
  const g = ctx.createLinearGradient(0, 580, 0, H);
  g.addColorStop(0, '#fff4d8'); g.addColorStop(1, '#e7cfa0');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(0, 620);
  for (let x = 0; x <= W; x += 80) {
    ctx.quadraticCurveTo(x + 40, 600 + Math.sin(x) * 8, x + 80, 620);
  }
  ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(150,110,60,.4)'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(0, 620);
  for (let x = 0; x <= W; x += 80) ctx.quadraticCurveTo(x + 40, 600 + Math.sin(x) * 8, x + 80, 620);
  ctx.stroke();
}

// ---------------- SHIP ----------------
function shipStatic(ctx) {
  sky(ctx, [[0, '#101c33'], [0.4, '#233e5e'], [0.68, '#4a6a83'], [1, '#8a7a63']]);
  // stars
  for (let i = 0; i < 90; i++) {
    const x = rand(W), y = rand(430);
    ctx.fillStyle = `rgba(255,240,200,${rand(0.9, 0.2)})`;
    ctx.beginPath(); ctx.arc(x, y, rand(2, 0.6), 0, TAU); ctx.fill();
  }
  // moon
  ctx.save();
  ctx.translate(1040, 130);
  ctx.globalAlpha = 0.16; ctx.fillStyle = '#ffe9b0';
  ctx.beginPath(); ctx.arc(0, 0, 150, 0, TAU); ctx.fill();
  ctx.globalAlpha = 1;
  fillEllipse(ctx, 0, 0, 74, 74, '#f6e7bd', '#c9a86e', 3);
  ctx.fillStyle = 'rgba(180,150,100,.35)';
  ctx.beginPath(); ctx.arc(-22, -14, 13, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(24, 18, 20, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(16, -30, 7, 0, TAU); ctx.fill();
  ctx.restore();
  // sea
  const sea = ctx.createLinearGradient(0, 470, 0, 640);
  sea.addColorStop(0, '#16324b'); sea.addColorStop(1, '#0b1c2c');
  ctx.fillStyle = sea;
  ctx.beginPath();
  ctx.moveTo(0, 500);
  for (let x = 0; x <= W; x += 60) ctx.quadraticCurveTo(x + 30, 488 + Math.sin(x * 0.03) * 6, x + 60, 500);
  ctx.lineTo(W, 640); ctx.lineTo(0, 640); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(160,205,215,.25)'; ctx.lineWidth = 3;
  for (let i = 0; i < 7; i++) {
    const y = 520 + i * 17;
    ctx.beginPath();
    for (let x = 0; x <= W; x += 50) ctx.lineTo(x, y + Math.sin(x * 0.02 + i) * 4);
    ctx.stroke();
  }
  // distant island silhouette
  ctx.fillStyle = '#0a1522';
  ctx.beginPath();
  ctx.moveTo(80, 500);
  ctx.bezierCurveTo(140, 455, 220, 470, 260, 500);
  ctx.closePath(); ctx.fill();
  // ship deck
  const deck = ctx.createLinearGradient(0, 590, 0, 720);
  deck.addColorStop(0, '#9a6438'); deck.addColorStop(1, '#5a3520');
  ctx.fillStyle = deck;
  ctx.beginPath();
  ctx.moveTo(0, 604); ctx.lineTo(W, 604); ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
  // planks
  ctx.strokeStyle = 'rgba(55,30,16,.55)'; ctx.lineWidth = 3;
  for (let i = 0; i < 8; i++) {
    ctx.beginPath(); ctx.moveTo(0, 618 + i * 15); ctx.lineTo(W, 618 + i * 15); ctx.stroke();
  }
  for (let x = 30; x < W; x += 170) {
    ctx.beginPath(); ctx.moveTo(x, 604); ctx.lineTo(x + 20, H); ctx.stroke();
  }
  // railing
  ctx.strokeStyle = '#4a2b18'; ctx.lineWidth = 9;
  ctx.beginPath(); ctx.moveTo(0, 586); ctx.lineTo(W, 586); ctx.stroke();
  ctx.lineWidth = 4;
  for (let x = 20; x < W; x += 64) {
    ctx.beginPath(); ctx.moveTo(x, 582); ctx.lineTo(x, 615); ctx.stroke();
  }
  // mast + rigging
  ctx.save();
  ctx.strokeStyle = '#3a2416'; ctx.lineWidth = 13; ctx.lineCap = 'round';
  ctx.beginPath(); ctx.moveTo(620, 610); ctx.lineTo(636, 60); ctx.stroke();
  ctx.strokeStyle = 'rgba(230,210,170,.35)'; ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath(); ctx.moveTo(632, 90 + i * 60); ctx.lineTo(900 + i * 70, 600); ctx.stroke();
  }
  // crow's nest
  ctx.fillStyle = '#4a2b18';
  ctx.fillRect(596, 130, 80, 14);
  ctx.restore();
  // hanging lanterns
  for (const [x, y] of [[300, 210], [980, 190]]) {
    ctx.strokeStyle = '#2a1a10'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(x, 120); ctx.lineTo(x, y); ctx.stroke();
    ctx.fillStyle = 'rgba(255,200,90,.28)';
    ctx.beginPath(); ctx.arc(x, y + 16, 44, 0, TAU); ctx.fill();
    fillRound(ctx, x - 15, y, 30, 36, 7, '#f3c05e', '#2a1a10', 3);
    ctx.fillStyle = '#2a1a10';
    ctx.fillRect(x - 14, y + 16, 28, 4);
  }
}

// ---------------- ICE ----------------
function iceStatic(ctx) {
  sky(ctx, [[0, '#1d3b5c'], [0.35, '#5b8fb0'], [0.65, '#bfe2e8'], [1, '#eef9f5']]);
  // aurora
  ctx.save();
  ctx.globalAlpha = 0.25;
  for (let i = 0; i < 3; i++) {
    ctx.fillStyle = ['#7ff0c8', '#a7c6ff', '#ffb6e6'][i];
    ctx.beginPath();
    ctx.moveTo(0, 90 + i * 30);
    ctx.bezierCurveTo(300, 30 + i * 40, 700, 150 + i * 20, W, 60 + i * 30);
    ctx.lineTo(W, 150 + i * 30);
    ctx.bezierCurveTo(700, 210 + i * 20, 300, 90 + i * 40, 0, 190 + i * 30);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  // stars
  for (let i = 0; i < 60; i++) {
    ctx.fillStyle = `rgba(255,255,255,${rand(0.7, 0.15)})`;
    ctx.beginPath(); ctx.arc(rand(W), rand(220), rand(1.8, 0.5), 0, TAU); ctx.fill();
  }
  // mountains
  const mtn = (pts, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], 620);
    pts.forEach(([x, y]) => ctx.lineTo(x, y));
    ctx.lineTo(1280, 620);
    ctx.closePath(); ctx.fill();
  };
  mtn([[0, 480], [160, 250], [300, 430], [470, 300], [640, 470], [820, 320], [980, 460], [1140, 300], [1280, 440]], '#8fb6c9');
  mtn([[0, 560], [200, 360], [380, 520], [560, 400], [760, 530], [960, 400], [1160, 530], [1280, 470]], '#6f9db4');
  ctx.fillStyle = 'rgba(255,255,255,.85)';
  [[160, 250], [470, 300], [820, 320], [1140, 300]].forEach(([x, y]) => {
    ctx.beginPath();
    ctx.moveTo(x - 50, y + 70); ctx.lineTo(x, y); ctx.lineTo(x + 50, y + 70);
    ctx.quadraticCurveTo(x, y + 40, x - 50, y + 70);
    ctx.fill();
  });
  // pines
  ctx.fillStyle = '#26404a';
  for (let i = 0; i < 18; i++) {
    const x = rand(W), y = 600 + rand(20), s = rand(1.3, 0.6);
    ctx.beginPath();
    ctx.moveTo(x, y - 60 * s); ctx.lineTo(x + 24 * s, y); ctx.lineTo(x - 24 * s, y);
    ctx.closePath(); ctx.fill();
  }
  // snow ground
  const snow = ctx.createLinearGradient(0, 600, 0, H);
  snow.addColorStop(0, '#f6ffff'); snow.addColorStop(1, '#c6e6ee');
  ctx.fillStyle = snow;
  ctx.beginPath();
  ctx.moveTo(0, 616);
  ctx.bezierCurveTo(240, 598, 440, 630, 660, 612);
  ctx.bezierCurveTo(900, 594, 1080, 630, 1280, 610);
  ctx.lineTo(1280, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = 'rgba(120,170,190,.55)'; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(0, 617);
  ctx.bezierCurveTo(240, 599, 440, 631, 660, 613);
  ctx.bezierCurveTo(900, 595, 1080, 631, 1280, 611); ctx.stroke();
  // cracks
  ctx.strokeStyle = 'rgba(140,190,205,.5)'; ctx.lineWidth = 2;
  for (let i = 0; i < 8; i++) {
    const x = 80 + i * 160, y = 660 + (i % 3) * 14;
    ctx.beginPath(); ctx.moveTo(x, y);
    ctx.lineTo(x + 40, y + 12); ctx.lineTo(x + 70, y + 2); ctx.lineTo(x + 110, y + 18);
    ctx.stroke();
  }
  // ice chunks
  for (let i = 0; i < 10; i++) {
    const x = rand(W), y = rand(700, 630);
    ctx.save(); ctx.translate(x, y);
    ctx.fillStyle = 'rgba(190,235,245,.9)';
    ctx.strokeStyle = 'rgba(100,150,170,.6)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(0, -18); ctx.lineTo(14, 4); ctx.lineTo(-12, 6); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.restore();
  }
}

// ---------------- CIRCUS ----------------
function circusStatic(ctx) {
  sky(ctx, [[0, '#190f1c'], [0.5, '#2e1822'], [1, '#4a2226']]);
  // tent stripes
  ctx.save();
  ctx.translate(W / 2, 380);
  for (let i = 0; i < 20; i++) {
    ctx.fillStyle = i % 2 ? 'rgba(148,36,44,.55)' : 'rgba(86,20,30,.4)';
    ctx.beginPath();
    ctx.moveTo(0, -380);
    ctx.lineTo(Math.cos((i / 20) * Math.PI - Math.PI) * 1900, 460);
    ctx.lineTo(Math.cos(((i + 1) / 20) * Math.PI - Math.PI) * 1900, 460);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  // bunting ropes
  ctx.strokeStyle = 'rgba(230,200,150,.35)'; ctx.lineWidth = 2;
  for (let row = 0; row < 2; row++) {
    ctx.beginPath(); ctx.moveTo(0, 80 + row * 60);
    ctx.quadraticCurveTo(640, 180 + row * 60, 1280, 70 + row * 60); ctx.stroke();
    for (let i = 0; i < 16; i++) {
      const p = i / 15;
      const x = p * 1280;
      const y = (1 - p) ** 2 * (80 + row * 60) + 2 * (1 - p) * p * (180 + row * 60) + p * p * (70 + row * 60);
      ctx.fillStyle = ['#d9452f', '#e9b44c', '#2f7d76'][(i + row) % 3];
      ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 16, y); ctx.lineTo(x + 8, y + 24); ctx.closePath(); ctx.fill();
    }
  }
  // tent poles
  ctx.fillStyle = '#3b2418';
  ctx.fillRect(80, 100, 16, 520);
  ctx.fillRect(1184, 100, 16, 520);
  ctx.fillStyle = '#e9b44c';
  ctx.beginPath(); ctx.arc(88, 96, 14, 0, TAU); ctx.fill();
  ctx.beginPath(); ctx.arc(1192, 96, 14, 0, TAU); ctx.fill();
  // audience silhouettes
  ctx.fillStyle = '#120a10';
  for (let i = 0; i < 34; i++) {
    const x = i * 39 + rand(8);
    ctx.beginPath(); ctx.arc(x, 556 + rand(6), rand(16, 11), 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.ellipse(x, 600, rand(26, 17), 30, 0, Math.PI, TAU); ctx.fill();
  }
  // ring ground
  const ring = ctx.createLinearGradient(0, 600, 0, H);
  ring.addColorStop(0, '#d8b077'); ring.addColorStop(1, '#8c6136');
  ctx.fillStyle = ring;
  ctx.beginPath();
  ctx.ellipse(W / 2, 730, 900, 160, 0, Math.PI, TAU);
  ctx.fill();
  ctx.strokeStyle = '#c9a86e'; ctx.lineWidth = 8;
  ctx.beginPath(); ctx.ellipse(W / 2, 700, 620, 120, 0, Math.PI, TAU); ctx.stroke();
  // spotlight cones
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  ctx.globalAlpha = 0.12;
  ctx.fillStyle = '#ffe9b0';
  ctx.beginPath(); ctx.moveTo(260, 0); ctx.lineTo(120, 700); ctx.lineTo(520, 700); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(1020, 0); ctx.lineTo(820, 700); ctx.lineTo(1200, 700); ctx.closePath(); ctx.fill();
  ctx.restore();
  // curtains side
  ctx.fillStyle = '#6b1d2a';
  for (const side of [0, 1]) {
    ctx.save();
    if (side) { ctx.translate(W, 0); ctx.scale(-1, 1); }
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(150, 0);
    ctx.bezierCurveTo(120, 180, 165, 320, 100, 460);
    ctx.bezierCurveTo(60, 540, 110, 620, 0, 700);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = 'rgba(30,8,14,.5)'; ctx.lineWidth = 4;
    for (let i = 0; i < 5; i++) {
      ctx.beginPath(); ctx.moveTo(30 + i * 22, 0);
      ctx.bezierCurveTo(20 + i * 26, 200, 50 + i * 24, 400, 40 + i * 20, 640);
      ctx.stroke();
    }
    ctx.restore();
  }
}

