};

export function drawArena(ctx, key, t, platforms) {
  const a = ARENAS[key];
  if (!a) return;
  ctx.drawImage(a.static(), 0, 0);
  a.dynamic(ctx, t);
  for (const p of platforms || []) a.platform(ctx, p);
}

