301:     ctx.beginPath();
302:     ctx.moveTo(0, 90 + i * 30);
303:     ctx.bezierCurveTo(300, 30 + i * 40, 700, 150 + i * 20, W, 60 + i * 30);
304:     ctx.lineTo(W, 150 + i * 30);
305:     ctx.bezierCurveTo(700, 210 + i * 20, 300, 90 + i * 40, 0, 190 + i * 30);
306:     ctx.closePath(); ctx.fill();
307:   }
308:   ctx.restore();
309:   // stars
310:   for (let i = 0; i < 60; i++) {
311:     ctx.fillStyle = `rgba(255,255,255,${rand(0.7, 0.15)})`;
312:     ctx.beginPath(); ctx.arc(rand(W), rand(220), rand(1.8, 0.5), 0, TAU); ctx.fill();
313:   }
314:   // mountains
315:   const mtn = (pts, color) => {
316:     ctx.fillStyle = color;
317:     ctx.beginPath();
318:     ctx.moveTo(pts[0][0], 620);
319:     pts.forEach(([x, y]) => ctx.lineTo(x, y));
320:     ctx.lineTo(1280, 620);
321:     ctx.closePath(); ctx.fill();
322:   };
323:   mtn([[0, 480], [160, 250], [300, 430], [470, 300], [640, 470], [820, 320], [980, 460], [1140, 300], [1280, 440]], '#8fb6c9');
324:   mtn([[0, 560], [200, 360], [380, 520], [560, 400], [760, 530], [960, 400], [1160, 530], [1280, 470]], '#6f9db4');
325:   ctx.fillStyle = 'rgba(255,255,255,.85)';
326:   [[160, 250], [470, 300], [820, 320], [1140, 300]].forEach(([x, y]) => {
327:     ctx.beginPath();
328:     ctx.moveTo(x - 50, y + 70); ctx.lineTo(x, y); ctx.lineTo(x + 50, y + 70);
329:     ctx.quadraticCurveTo(x, y + 40, x - 50, y + 70);
330:     ctx.fill();
331:   });
332:   // pines
333:   ctx.fillStyle = '#26404a';
334:   for (let i = 0; i < 18; i++) {
335:     const x = rand(W), y = 600 + rand(20), s = rand(1.3, 0.6);
336:     ctx.beginPath();
337:     ctx.moveTo(x, y - 60 * s); ctx.lineTo(x + 24 * s, y); ctx.lineTo(x - 24 * s, y);
338:     ctx.closePath(); ctx.fill();
339:   }
340:   // snow ground
341:   const snow = ctx.createLinearGradient(0, 600, 0, H);
342:   snow.addColorStop(0, '#f6ffff'); snow.addColorStop(1, '#c6e6ee');
343:   ctx.fillStyle = snow;
344:   ctx.beginPath();
345:   ctx.moveTo(0, 616);
346:   ctx.bezierCurveTo(240, 598, 440, 630, 660, 612);
347:   ctx.bezierCurveTo(900, 594, 1080, 630, 1280, 610);
348:   ctx.lineTo(1280, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
349:   ctx.strokeStyle = 'rgba(120,170,190,.55)'; ctx.lineWidth = 4;
350:   ctx.beginPath(); ctx.moveTo(0, 617);
351:   ctx.bezierCurveTo(240, 599, 440, 631, 660, 613);
352:   ctx.bezierCurveTo(900, 595, 1080, 631, 1280, 611); ctx.stroke();
353:   // cracks
354:   ctx.strokeStyle = 'rgba(140,190,205,.5)'; ctx.lineWidth = 2;
355:   for (let i = 0; i < 8; i++) {
356:     const x = 80 + i * 160, y = 660 + (i % 3) * 14;
357:     ctx.beginPath(); ctx.moveTo(x, y);
358:     ctx.lineTo(x + 40, y + 12); ctx.lineTo(x + 70, y + 2); ctx.lineTo(x + 110, y + 18);
359:     ctx.stroke();
