365:     ctx.fillStyle = 'rgba(190,235,245,.9)';
366:     ctx.strokeStyle = 'rgba(100,150,170,.6)'; ctx.lineWidth = 2;
367:     ctx.beginPath(); ctx.moveTo(0, -18); ctx.lineTo(14, 4); ctx.lineTo(-12, 6); ctx.closePath();
368:     ctx.fill(); ctx.stroke();
369:     ctx.restore();
370:   }
371: }
