373: // ---------------- CIRCUS ----------------
374: function circusStatic(ctx) {
375:   sky(ctx, [[0, '#190f1c'], [0.5, '#2e1822'], [1, '#4a2226']]);
376:   // tent stripes
377:   ctx.save();
378:   ctx.translate(W / 2, 380);
379:   for (let i = 0; i < 20; i++) {
380:     ctx.fillStyle = i % 2 ? 'rgba(148,36,44,.55)' : 'rgba(86,20,30,.4)';
381:     ctx.beginPath();
382:     ctx.moveTo(0, -380);
383:     ctx.lineTo(Math.cos((i / 20) * Math.PI - Math.PI) * 1900, 460);
384:     ctx.lineTo(Math.cos(((i + 1) / 20) * Math.PI - Math.PI) * 1900, 460);
385:     ctx.closePath(); ctx.fill();
386:   }
387:   ctx.restore();
388:   // bunting ropes
389:   ctx.strokeStyle = 'rgba(230,200,150,.35)'; ctx.lineWidth = 2;
390:   for (let row = 0; row < 2; row++) {
391:     ctx.beginPath(); ctx.moveTo(0, 80 + row * 60);
392:     ctx.quadraticCurveTo(640, 180 + row * 60, 1280, 70 + row * 60); ctx.stroke();
393:     for (let i = 0; i < 16; i++) {
394:       const p = i / 15;
395:       const x = p * 1280;
396:       const y = (1 - p) ** 2 * (80 + row * 60) + 2 * (1 - p) * p * (180 + row * 60) + p * p * (70 + row * 60);
397:       ctx.fillStyle = ['#d9452f', '#e9b44c', '#2f7d76'][(i + row) % 3];
398:       ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + 16, y); ctx.lineTo(x + 8, y + 24); ctx.closePath(); ctx.fill();
399:     }
400:   }
401:   // tent poles
402:   ctx.fillStyle = '#3b2418';
403:   ctx.fillRect(80, 100, 16, 520);
404:   ctx.fillRect(1184, 100, 16, 520);
405:   ctx.fillStyle = '#e9b44c';
406:   ctx.beginPath(); ctx.arc(88, 96, 14, 0, TAU); ctx.fill();
407:   ctx.beginPath(); ctx.arc(1192, 96, 14, 0, TAU); ctx.fill();
408:   // audience silhouettes
409:   ctx.fillStyle = '#120a10';
410:   for (let i = 0; i < 34; i++) {
411:     const x = i * 39 + rand(8);
412:     ctx.beginPath(); ctx.arc(x, 556 + rand(6), rand(16, 11), 0, TAU); ctx.fill();
413:     ctx.beginPath(); ctx.ellipse(x, 600, rand(26, 17), 30, 0, Math.PI, TAU); ctx.fill();
414:   }
415:   // ring ground
416:   const ring = ctx.createLinearGradient(0, 600, 0, H);
417:   ring.addColorStop(0, '#d8b077'); ring.addColorStop(1, '#8c6136');
418:   ctx.fillStyle = ring;
419:   ctx.beginPath();
420:   ctx.ellipse(W / 2, 730, 900, 160, 0, Math.PI, TAU);
421:   ctx.fill();
422:   ctx.strokeStyle = '#c9a86e'; ctx.lineWidth = 8;
423:   ctx.beginPath(); ctx.ellipse(W / 2, 700, 620, 120, 0, Math.PI, TAU); ctx.stroke();
424:   // spotlight cones
425:   ctx.save();
426:   ctx.globalCompositeOperation = 'screen';
427:   ctx.globalAlpha = 0.12;
428:   ctx.fillStyle = '#ffe9b0';
429:   ctx.beginPath(); ctx.moveTo(260, 0); ctx.lineTo(120, 700); ctx.lineTo(520, 700); ctx.closePath(); ctx.fill();
430:   ctx.beginPath(); ctx.moveTo(1020, 0); ctx.lineTo(820, 700); ctx.lineTo(1200, 700); ctx.closePath(); ctx.fill();
431:   ctx.restore();
432:   // curtains side
433:   ctx.fillStyle = '#6b1d2a';
434:   for (const side of [0, 1]) {
435:     ctx.save();
436:     if (side) { ctx.translate(W, 0); ctx.scale(-1, 1); }
437:     ctx.beginPath();
438:     ctx.moveTo(0, 0); ctx.lineTo(150, 0);
439:     ctx.bezierCurveTo(120, 180, 165, 320, 100, 460);
440:     ctx.bezierCurveTo(60, 540, 110, 620, 0, 700);
441:     ctx.closePath(); ctx.fill();
442:     ctx.strokeStyle = 'rgba(30,8,14,.5)'; ctx.lineWidth = 4;
443:     for (let i = 0; i < 5; i++) {
444:       ctx.beginPath(); ctx.moveTo(30 + i * 22, 0);
445:       ctx.bezierCurveTo(20 + i * 26, 200, 50 + i * 24, 400, 40 + i * 20, 640);
446:       ctx.stroke();
447:     }
448:     ctx.restore();
449:   }
450: }
