647:       ctx.moveTo(p.x + p.w - 12, p.y); ctx.lineTo(p.x + p.w - 12, p.y - 300); ctx.stroke();
648:     },
649:   },
650: };
651: 
652: export function drawArena(ctx, key, t, platforms) {
653:   const a = ARENAS[key];
654:   if (!a) return;
655:   ctx.drawImage(a.static(), 0, 0);
656:   a.dynamic(ctx, t);
657:   for (const p of platforms || []) a.platform(ctx, p);
658: }

