await page.keyboard.up('ArrowRight'); await page.keyboard.up('f'); await page.waitForTimeout(2500);
await page.screenshot({path:'/tmp/opencode/latest.jpg',type:'jpeg',quality:80});
console.log(JSON.stringify({errors,started:await page.locator('#titleUI').getAttribute('class'),touch:await page.locator('#touch').getAttribute('class'),canvas:await page.locator('#game').evaluate(c=>({width:c.width,height:c.height,box:c.getBoundingClientRect().toJSON()}))}));
await browser.close();
