173:     "jump dash fire";
174:   gap: clamp(6px, 1.2vh, 12px);
175:   align-items: end;
176:   justify-items: end;
177:   pointer-events: none;
178: }
179: 
180: .tbtn {
181:   pointer-events: auto;
182:   touch-action: none;
183:   font-family: "Georgia", serif;
184:   font-weight: 900;
185:   font-size: clamp(8px, 1.25vh, 13px);
186:   letter-spacing: .08em;
187:   color: #fdf6e3;
188:   width: clamp(52px, 8.6vh, 78px);
189:   height: clamp(52px, 8.6vh, 78px);
190:   border-radius: 50%;
191:   border: 2px solid rgba(253, 246, 227, .55);
192:   background: radial-gradient(circle at 35% 28%, rgba(80,60,48,.85), rgba(30,20,16,.82));
193:   box-shadow: 0 4px 12px rgba(0,0,0,.45);
194:   display: grid;
195:   place-items: center;
196:   line-height: 1;
197:   padding: 0;
198: }
199: 
200: .tbtn span { transform: translateY(1px); }
201: .tbtn em {
202:   display: block;
203:   font-style: normal;
204:   font-size: .72em;
205:   opacity: .8;
206:   margin-top: 3px;
207:   letter-spacing: .04em;
208: }
209: .tbtn:active, .tbtn.on { transform: scale(.93); background: radial-gradient(circle at 35% 28%, #e9b44c, #a05f1d); color: #2b1d17; }
210: .tbtn-fire { background: radial-gradient(circle at 35% 28%, rgba(190,70,50,.9), rgba(90,22,18,.85)); width: clamp(60px, 10vh, 88px); height: clamp(60px, 10vh, 88px); }
211: .tbtn-jump { background: radial-gradient(circle at 35% 28%, rgba(60,130,120,.9), rgba(20,60,58,.85)); }
212: .tbtn-dash { background: radial-gradient(circle at 35% 28%, rgba(90,90,140,.9), rgba(30,30,60,.85)); grid-area: dash; }
213: .tbtn-super {
214:   grid-area: sup;
215:   width: clamp(46px, 7.4vh, 66px);
216:   height: clamp(46px, 7.4vh, 66px);
217:   background: radial-gradient(circle at 35% 28%, rgba(234,180,76,.95), rgba(120,70,20,.9));
218:   color: #2b1d17;
219: }
220: .tbtn-sm {
221:   grid-area: swap;
222:   width: clamp(44px, 7vh, 62px);
223:   height: clamp(44px, 7vh, 62px);
224:   font-size: clamp(7px, 1.05vh, 10px);
225: }
226: .tbtn-jump { grid-area: jump; }
227: .tbtn-fire { grid-area: fire; }
228: .tbtn-super em { font-size: .62em; }
229: 
230: .pause-btn {
231:   position: absolute;
232:   top: max(10px, env(safe-area-inset-top));
233:   right: max(10px, env(safe-area-inset-right));
234:   z-index: 31;
235:   width: 34px;
236:   height: 34px;
237:   display: grid;
238:   place-items: center;
239:   border-radius: 50%;
240:   border: 2px solid rgba(253, 246, 227, .5);
241:   background: rgba(20, 14, 11, .45);
242:   color: #fdf6e3;
243:   font-family: sans-serif;
244:   font-size: 13px;
245:   font-weight: 800;
246:   letter-spacing: 1px;
247:   cursor: pointer;
248: }
249: 
250: /* Portrait phones: park the controls under the screen instead of over it */
251: @media (orientation: portrait) and (pointer: coarse) {
252:   #app { place-items: start center; padding-top: max(2vh, env(safe-area-inset-top)); }
253:   .stage { width: 100vw; height: 56.25vw; box-shadow: 0 0 0 3px #2a1d16, 0 8px 30px #000; }
254:   .touch { inset: auto 0 0 0; height: calc(100vh - 56.25vw - 2vh); pointer-events: none; }
255:   .pad { left: max(22px, env(safe-area-inset-left)); bottom: auto; top: 12%; width: min(34vw, 190px); }
256:   .right-btns { right: max(18px, env(safe-area-inset-right)); bottom: auto; top: 10%; transform: scale(1.05); }
257:   .tbtn { width: min(14vw, 76px); height: min(14vw, 76px); font-size: 10px; }
258:   .tbtn-fire { width: min(17vw, 88px); height: min(17vw, 88px); }
259:   .tbtn-super, .tbtn-sm { width: min(11vw, 64px); height: min(11vw, 64px); }
260:   .title-hint { display: none; }
261:   .pause-btn { top: 6px; right: 8px; width: 30px; height: 30px; }
262: }
263: 
264: /* Very short landscape phones */
265: @media (orientation: landscape) and (max-height: 430px) {
266:   .pad { width: 88px; }
267:   .right-btns { transform: scale(.9); transform-origin: bottom right; }
268:   .title-hint { display: none; }
269: }

input.command:
node --input-type=module - <<'JS'
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch(config.browser.launchOptions);
const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
const page=await context.newPage(); const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',m=>{if(m.type()==='error'&&!m.text().includes('404'))errors.push(m.text())});
await page.goto('http://127.0.0.1:3000',{waitUntil:'load'}); await page.waitForTimeout(300);
await page.locator('#startBtn').click(); await page.waitForTimeout(100);
const before=await page.locator('#tWeaponName').textContent(); await page.locator('#tWeapon').tap();
const after=await page.locator('#tWeaponName').textContent();
const fire=page.locator('#tFire'); await fire.dispatchEvent('pointerdown',{pointerId:5,pointerType:'touch',isPrimary:true,clientX:0,clientY:0,button:0,buttons:1});
const firePressed=await fire.evaluate(e=>e.classList.contains('on'));
await fire.dispatchEvent('pointerup',{pointerId:5,pointerType:'touch',isPrimary:true,clientX:0,clientY:0,button:0,buttons:0});
await page.locator('#tJump').tap(); await page.locator('#tDash').tap();
const metrics=await page.evaluate(()=>({viewport:[innerWidth,innerHeight],stage:document.querySelector('.stage').getBoundingClientRect().toJSON(),pad:document.querySelector('#pad').getBoundingClientRect().toJSON(),controls:document.querySelector('.right-btns').getBoundingClientRect().toJSON()}));
await page.waitForTimeout(500); await page.screenshot({path:'/tmp/opencode/latest.jpg',type:'jpeg',quality:80});
console.log(JSON.stringify({errors,before,after,firePressed,metrics})); await browser.close();
JS

